484	void FileSegment::complete(State state)
485	{
486	    std::lock_guard cache_lock(cache->mutex);
487	    std::lock_guard segment_lock(mutex);
488	
489	    assertNotDetached(segment_lock);
490	
491	    bool is_downloader = isDownloaderImpl(segment_lock);
492	    if (!is_downloader)
493	    {
494	        cv.notify_all();
495	        throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR,
496	                        "File segment can be completed only by downloader or downloader's FileSegmentsHodler");
497	    }
498	
499	    if (state != State::DOWNLOADED
500	        && state != State::PARTIALLY_DOWNLOADED
501	        && state != State::PARTIALLY_DOWNLOADED_NO_CONTINUATION)
502	    {
503	        cv.notify_all();
504	        throw Exception(ErrorCodes::REMOTE_FS_OBJECT_CACHE_ERROR,
505	                        "Cannot complete file segment with state: {}", stateToString(state));
506	    }
507	
508	    if (state == State::DOWNLOADED)
509	        setDownloaded(segment_lock);
510	
511	    download_state = state;
512	
513	    try
514	    {
515	        completeImpl(cache_lock, segment_lock);
516	    }
517	    catch (...)
518	    {
519	        if (!downloader_id.empty() && is_downloader)
520	            downloader_id.clear();
521	
522	        cv.notify_all();
523	        throw;
524	    }
525	
526	    cv.notify_all();
527	}
