538	void FileSegment::completeUnlocked(std::lock_guard<std::mutex> & cache_lock, std::lock_guard<std::mutex> & segment_lock)
539	{
540	    bool is_last_holder = cache->isLastFileSegmentHolder(key(), offset(), cache_lock, segment_lock);
541	
542	    if (is_last_holder && download_state == State::SKIP_CACHE)
543	    {
544	        cache->remove(key(), offset(), cache_lock, segment_lock);
545	        return;
546	    }
547	
548	    if (download_state == State::SKIP_CACHE || is_detached)
549	        return;
550	
551	    if (isDownloaderImpl(segment_lock)
552	        && download_state != State::DOWNLOADED
553	        && getDownloadedSize(segment_lock) == range().size())
554	    {
555	        setDownloaded(segment_lock);
556	    }
557	
558	    assertNotDetached(segment_lock);
559	
560	    if (download_state == State::DOWNLOADING || download_state == State::EMPTY)
561	    {
562	        /// Segment state can be changed from DOWNLOADING or EMPTY only if the caller is the
563	        /// downloader or the only owner of the segment.
564	
565	        bool can_update_segment_state = isDownloaderImpl(segment_lock) || is_last_holder;
566	
567	        if (can_update_segment_state)
568	            download_state = State::PARTIALLY_DOWNLOADED;
569	    }
570	
571	    try
572	    {
573	        completeImpl(cache_lock, segment_lock);
574	    }
575	    catch (...)
576	    {
577	        if (!downloader_id.empty() && isDownloaderImpl(segment_lock))
578	            downloader_id.clear();
579	
580	        cv.notify_all();
581	        throw;
582	    }
583	
584	    cv.notify_all();
585	}
