713	void FileSegment::assertDetachedStatus(std::lock_guard<std::mutex> & segment_lock) const
714	{
715	    /// Detached file segment is allowed to have only a certain subset of states.
716	    /// It should be either EMPTY or one of the finalized states.
717	
718	    if (download_state != State::EMPTY && !hasFinalizedState())
