727	FileSegmentPtr FileSegment::getSnapshot(const FileSegmentPtr & file_segment, std::lock_guard<std::mutex> & /* cache_lock */)
728	{
729	    auto snapshot = std::make_shared<FileSegment>(
730	        file_segment->offset(),
731	        file_segment->range().size(),
732	        file_segment->key(),
733	        nullptr,
734	        State::EMPTY);
735	
736	    snapshot->hits_count = file_segment->getHitsCount();
737	    snapshot->ref_count = file_segment.use_count();
738	    snapshot->downloaded_size = file_segment->getDownloadedSize();
739	    snapshot->download_state = file_segment->state();
740	    snapshot->is_persistent = file_segment->isPersistent();
741	
742	    return snapshot;
743	}
