752	void FileSegment::detach(
753	    std::lock_guard<std::mutex> & /* cache_lock */,
754	    std::lock_guard<std::mutex> & segment_lock)
755	{
756	    /// Now detached status can be in 2 cases, which do not do any complex logic:
757	    /// 1. there is only 1 remaining file segment holder
758	    ///    && it does not need this segment anymore
759	    ///    && this file segment was in cache and needs to be removed
760	    /// 2. in read_from_cache_if_exists_otherwise_bypass_cache case
761	    if (is_detached)
762	        return;
763	
764	    markAsDetached(segment_lock);
765	    download_state = State::PARTIALLY_DOWNLOADED_NO_CONTINUATION;
766	    downloader_id.clear();
767	
768	    LOG_TEST(log, "Detached file segment: {}", getInfoForLogImpl(segment_lock));
769	}
